export const BODY: string = "\n<p>أحد عشر مرشحًا خيارات كثيرة: كل منها يغيّر جو صورة، والخطأ قد يجعل صورة جيدة تبدو رخيصة أو غريبة.</p>\n<p>مقارنة المرشحات جنبًا إلى جنب هي أسرع طريقة لتعلمها: بمجرد أن تعرف ما يفعله كل منها، يصبح الاختيار سريعًا وتكسب صورك مظهرًا متسقًا.</p>\n<p>يقارن هذا المقال الأنماط الـ11 مباشرة: فيم تختلف وأي مواضيع تناسب كلًا منها وكيف تبني عادة مرشح متسقة في عملك.</p>\n<h2 id=\"why-compare-filters\">لماذا تقارن المرشحات</h2>\n<p>المرشحات تبدو متشابهة في شبكة صغيرة، لكنها تتصرف بشكل مختلف جدًا بالحجم الكامل: مرشح يبدو دافئًا في مصغرة قد يحوّل وجهًا إلى برتقالي في معاينة كاملة.</p>\n<p>ومقارنتها في نفس الصورة تُظهر الفروق بوضوح: نفس البورتريه بفينتج وسيبيا وأبيض وأسود نوير يبدو كثلاث صور مختلفة. والمقارنة تتجنب أيضًا أكثر خطأ مرشح شيوعًا: استخدام مرشح مختلف في كل صورة: خلاصة بمرشحات مختلطة تبدو عشوائية، بينما خلاصة متسقة تبني أسلوبًا.</p>\n<p>تعلم المرشحات مرة، في صور اختبار قليلة، ويصبح الاختيار سريعًا: ستعرف أي مرشح يناسب بورتريه أو منظرًا أو منتجًا دون تجربة الأحد عشر.</p>\n<h2 id=\"vintage-vs-sepia\">فينتج أم سيبيا</h2>\n<p>فينتج وسيبيا يشعران بالحنين، لكنهما يختلفان في القوة: سيبيا يضيف صبغة بنية دافئة وقوية، بينما فينتج يبهت الألوان بلطف، بمظهر فيلم أخف.</p>\n<p>سيبيا يناسب صورًا تاريخية وذكريات عائلية وأي صورة يجب أن تشعر بأنها من عصر آخر: الصبغة البنية لا تُخطأ ولافتة. وفينتج يناسب صورًا عفوية ومنشورات اجتماعية، حيث الحنين يجب أن يشعر خفيفًا: يضيف جوًا دون النغمة البنية القوية التي يجلبها سيبيا.</p>\n<p>جرّب الاثنين في نفس الصورة وقارن: الصحيح غالبًا يشعر بأنه ينتمي إلى المشهد، بينما الخطأ يشعر كتنكر.</p>\n<h2 id=\"grayscale-vs-noir\">تدرج رمادي أم أبيض وأسود نوير</h2>\n<p>تدرج رمادي يزيل اللون ويترك صورة نظيفة ومحايدة بالأبيض والأسود: إنها صادقة وهادئة، تُظهر الصورة كما هي بالضبط، دون لون.</p>\n<p>وأبيض وأسود نوير يزيل اللون ويضيف تباينًا قويًا: تتعمق السود وتفتّح البيض وتكسب الصورة جودة درامية كفيلم. واستخدم تدرج رمادي عندما يجب أن تشعر الصورة بالهدوء والتوثيق: واستخدم أبيض وأسود نوير عندما يجب أن تشعر بالدراما، بظلال قوية وإضاءات بارزة.</p>\n<p>وكلاهما يناسب عمارة وتصوير شوارع وصورًا شخصية بتعبيرات قوية: الاختيار يعتمد على إن أردت أبيض وأسود هادئًا أو دراميًا.</p>\n<h2 id=\"warm-vs-cool\">دافئ أم بارد</h2>\n<p>دافئ يضيف صبغة ذهبية تشعر بالشمس والترحيب: يناسب صورًا شخصية وطعامًا ومناظر، حيث توهج دافئ يجعل الصورة تشعر بالترحيب.</p>\n<p>وبارد يضيف صبغة زرقاء تشعر بالهدوء والحدة: يناسب مشاهد شتاء وعمارة ومنتجات تقنية، حيث لوحة باردة تشعر بالحداثة والنظافة. والاختيار يعتمد على الجو الذي تريده: مرشح دافئ على مشهد ثلجي يشعر بالخطأ، بينما مرشح بارد على غروب شاطئ يصارع الدفء الطبيعي.</p>\n<p>جرّب الاثنين في نفس الصورة وقارن: الفرق يقفز إلى العين فورًا، والصحيح غالبًا يشعر بأنه ينتمي إلى المشهد.</p>\n<h2 id=\"matte-fade-vs-golden-hour\">باهت غير لامع أم ساعة ذهبية</h2>\n<p>باهت غير لامع يلطّف السود، معطيًا الصورة جودة باهتة كفيلم: يناسب صورًا شخصية وصور أسلوب حياة، حيث جو ناعم وحالم يعمل جيدًا.</p>\n<p>وساعة ذهبية تحاكي ضوء الغروب الدافئ: تضيف توهجًا ذهبيًا يناسب مناظر وصورًا شخصية وأي صورة ملتقطة بضوء دافئ. وباهت غير لامع يتعلق بالنعومة، بينما ساعة ذهبية تتعلق بالدفء: صورة قد تكون ناعمة دون أن تكون دافئة، ودافئة دون أن تكون ناعمة، فالمرشحان يخدمان جوين مختلفين.</p>\n<p>لبورتريه حالم، باهت غير لامع هو الخيار الأفضل: ولمنظر غروب، ساعة ذهبية هي الواضحة، لأنها تعزز الضوء الموجود أصلًا.</p>\n<h2 id=\"high-contrast-filter\">تباين عالٍ ودرامي</h2>\n<p>تباين عالٍ يضيف قوة بتعميق الظلال وتفتيح الإضاءات: يناسب مناظر وعمارة وأي صورة تشعر بالتسطح والرمادية.</p>\n<p>ودرامي يذهب أبعد، معمّقًا الظلال بعدوانية أكثر لجو كئيب وسينمائي: يناسب سماوات عاصفة وليالي مدن وصورًا تحريرية لافتة. وكلاهما قد يكون قويًا جدًا للصور الشخصية: ظلال عميقة تسنّ الوجه وتجعل البشرة تبدو قاسية، فاستخدمهما في أشخاص فقط عندما يطلب الجو ذلك.</p>\n<p>وراجع الإضاءات بعد تطبيق أي منهما: الغيوم والأسطح البيضاء تقص أولًا، متحولة إلى بياض بلا ملامح.</p>\n<h2 id=\"invert-filter\">عكس: الحالة المنفصلة</h2>\n<p>عكس يقلب كل لون إلى عكسه، محولًا الصورة إلى سالب: إنه أكثر مرشح غير عادي في المجموعة، ويناسب نطاقًا ضيقًا من الاستخدامات.</p>\n<p>لمعظم الصور، عكس حداثة أكثر من تعديل عملي: بورتريه معكوس يبدو غريبًا، ومنظر معكوس يبدو أجنبيًا. واستخدم عكس لغرض إبداعي محدد: تأثير فني أو رسم لافت أو مراجعة بنية صورة: وصورة واحدة معكوسة في سلسلة قد تكون لافتة.</p>\n<p>ولا تبنِ مظهرًا متسقًا حول عكس: خلاصة صور معكوسة مربكة، بينما صورة معكوسة واحدة بين أخرى عادية تجذب النظر.</p>\n<h2 id=\"filters-for-portraits\">مرشحات للصور الشخصية مقارنة</h2>\n<p>فينتج ودافئ وباهت غير لامع هي أفضل مرشحات بورتريه: تضيف جوًا بشدة معتدلة دون تغيير الوجه، وهو ما يحتاجه بورتريه.</p>\n<p>وأبيض وأسود نوير يناسب صورًا شخصية بتعبيرات قوية: الأبيض والأسود الدرامي يؤكد العينين والعاطفة، لهذا هو مرشح بورتريه كلاسيكي. وتباين عالٍ ودرامي هما أسوأ مرشحات بورتريه لمعظم الوجوه: ظلال عميقة تسنّ البشرة وتجعل البورتريه يشعر بالقسوة.</p>\n<p>وبارد قد يعمل في بورتريه ملتقط بضوء بارد، لكنه قد يجعل البشرة أيضًا تبدو شاحبة وبلا حياة: جرّبه على الوجه قبل الالتزام.</p>\n<h2 id=\"filters-for-landscapes\">مرشحات للمناظر الطبيعية مقارنة</h2>\n<p>ساعة ذهبية هي أفضل مرشح منظر لضوء دافئ: تعزز توهج الغروب دون تغيير طابع المشهد.</p>\n<p>ودرامي يناسب مناظر كئيبة بسماوات عاصفة: ظلال عميقة تضيف وزنًا إلى الغيوم والجبال، معطية المشهد جوًا سينمائيًا. وفينتج وباهت غير لامع يناسبان مناظر ناعمة وحالمة: صباح ضبابي أو حقل هادئ يكسبان جوًا ناعمًا وحنينًا بمرشح باهت.</p>\n<p>وتجنب بارد في منظر دافئ: غروب بصبغة زرقاء يصارع الدفء الطبيعي، والنتيجة تبدو كخطأ أكثر من أسلوب.</p>\n<h2 id=\"filters-for-food\">مرشحات للطعام مقارنة</h2>\n<p>دافئ وساعة ذهبية هما أفضل مرشحات طعام: يعززان ألوانًا غنية وشهية، ويجعلان الأطباق تبدو طازجة وجذابة.</p>\n<p>وفينتج بشدة منخفضة قد يعمل أيضًا للطعام، خاصة لجو ريفي أو منزلي: المظهر الباهت يناسب طعامًا مريحًا ووصفات عائلية. وبارد هو أسوأ مرشح طعام: صبغة زرقاء تجعل الأطباق تبدو باردة وغير شهية، وهو عكس ما يجب أن تفعله صورة طعام.</p>\n<p>وراجع الأحمر بعد الترشيح: طماطم ولحم وتوت قد تصبح أحمر ساطعًا غير طبيعي بمرشح قوي، ما يجعل الطعام يبدو أقل شهية.</p>\n<h2 id=\"filters-for-products\">مرشحات للمنتجات مقارنة</h2>\n<p>المنتجات تحتاج لونًا دقيقًا، فمعظم المرشحات خطأ لها: مرشح يغيّر لون منتج يخدع المشتري ويضر بالثقة.</p>\n<p>تباين عالٍ بشدة منخفضة قد يعمل للمنتجات، مضيفًا تعريفًا دون تغيير اللون كثيرًا: دفعة صغيرة تجعل العنصر يبرز عن الخلفية. ودافئ بشدة منخفضة يناسب منتجات مصورة بضوء دافئ: يعزز التوهج الطبيعي دون تحريك لون المنتج.</p>\n<p>ولكتالوج، تخطَ المرشحات تمامًا أو استخدم نفس المرشح الناعم في كل صورة: الاتساق يهم أكثر من الأسلوب، واللون الدقيق يهم أكثر من كل شيء.</p>\n<h2 id=\"choosing-consistent-look\">كيف تختار مظهرًا متسقًا</h2>\n<p>مرشح متسق في صورك يخلق أسلوبًا مميزًا: المتابعون يتعلمون التعرف على عملك قبل قراءة اسمك، ما يبني هوية بصرية.</p>\n<p>اختر مرشحًا وشدة، واستخدمهما لسلسلة كاملة: خلاصة حيث كل صورة تشترك في نفس فينتج بنسبة 50 بالمئة تبدو معتنى بها، بينما مرشحات مختلطة تبدو عشوائية. وجرّب المرشح في أنواع صور مختلفة قبل الالتزام: مرشح يناسب مناظر قد لا يناسب صورًا شخصية، ومظهر متسق يحتاج مرشحًا يعمل في الاثنين.</p>\n<p>وراجع اختيار مرشحك من حين لآخر: الأنماط تتغير، ومرشح شعر بالانتعاش العام الماضي قد يشعر بالقدم الآن، فحدّثه عندما يتطور عملك.</p>\n<h2 id=\"intensity-choices\">الشدة: القرار الحقيقي</h2>\n<p>اختيار المرشح يهم أقل من الشدة: مرشح فينتج بنسبة 100 بالمئة ونفس المرشح بنسبة 50 بالمئة يبدوان كتعديلين مختلفين، والقيمة الأصغر غالبًا تبدو أفضل.</p>\n<p>ابدأ بشدة كاملة لرؤية طابع المرشح، ثم اخفضها حتى يشعر التأثير جيدًا: المعاينة تتحدث مباشرة، فتستطيع إيجاد النقطة المثالية بسرعة. وللصور الشخصية، شدة أقل 40 إلى 60 بالمئة غالبًا أفضل: تضيف جوًا دون تغيير الوجه، وهو ما يحتاجه بورتريه.</p>\n<p>وللمناظر، شدة أعلى 60 إلى 80 بالمئة قد تعمل: المشهد يتحمل تأثيرًا أقوى دون أن يبدو مصطنعًا، لأنه لا بشرة لحمايتها.</p>\n<h2 id=\"mixing-filters\">كيف تمزج مرشحات في خلاصة</h2>\n<p>مزج المرشحات هو أكثر خطأ اتساق شيوعًا: خلاصة حيث صورة فينتج والتالية درامي والثالثة بارد تبدو عشوائية وبلا خطة.</p>\n<p>استخدم مرشحًا واحدًا لسلسلة كاملة، وغيّر فقط الشدة: خلاصة فينتج قد يكون لها بورتريهات بنسبة 40 بالمئة ومناظر بنسبة 60 بالمئة، ويبقى المظهر متسقًا. وعندما تحتاج صورة واحدة مرشحًا مختلفًا، استخدمه كاستثناء لا كعادة: بورتريه بأبيض وأسود نوير في خلاصة فينتج قد يكون لافتًا، بينما خمسة منها تكسر المظهر.</p>\n<p>وخطط للمرشح قبل التصوير، عندما تستطيع: سلسلة ملتقطة بمرشح في الذهن تبدو أكثر تماسكًا من سلسلة مرشحة بعدها، عشوائيًا.</p>\n<h2 id=\"trends-vs-timeless\">اتجاهات أم مرشحات خالدة</h2>\n<p>أنماط المرشحات تتبع اتجاهات مثل أي شيء آخر: فينتج كان شائعًا قبل عقد، ودرامي شائع الآن، واللون الأدنى والطبيعي لا يمر أبدًا.</p>\n<p>لعمل يجب أن يدوم، اختر مرشحًا خالدًا: فينتج ناعم بشدة منخفضة يبدو جيدًا بعد عشر سنوات كما اليوم، بينما درامي قاسٍ قد يشعر بالقدم بسرعة. ولمنشورات اجتماعية تعيش يومًا، الاتجاهات جيدة: مرشح درامي يطابق الأسلوب الحالي قد يعزز التفاعل، وسيُنسى المنشور قبل أن يبدو المرشح قديمًا بكثير.</p>\n<p>وعند الشك، اذهب بلطف: مرشح دقيق لا يكون خطأ أبدًا، ويترك الصورة تحمل الصورة بدل التأثير.</p>\n<h2 id=\"cheat-sheet\">كيف تختار مرشحًا: ورقة غش سريعة</h2>\n<p>استخدم فينتج أو باهت غير لامع للصور الشخصية والصور العفوية، بشدة 40 إلى 60 بالمئة: يضيفان جوًا دون تغيير الوجه.</p>\n<p>استخدم ساعة ذهبية أو درامي للمناظر، بشدة 60 إلى 80 بالمئة: يعززان الضوء والجو دون إغراق المشهد. واستخدم دافئًا للطعام والمنتجات بضوء دافئ، بشدة 40 إلى 60 بالمئة: يعزز ألوانًا شهية دون تحريكها.</p>\n<p>واستخدم تدرج رمادي أو أبيض وأسود نوير لعمارة وتصوير شوارع وبورتريهات درامية: اختر تدرج رمادي للهدوء وأبيض وأسود نوير للدراما.</p>\n<h2 id=\"filters-for-weddings\">مرشحات لصور الزفاف مقارنة</h2>\n<p>فينتج وباهت غير لامع هما أفضل مرشحات زفاف: يضيفان جوًا ناعمًا ورومانسيًا بشدة معتدلة، دون تغيير الوجوه ولا الفستان الأبيض.</p>\n<p>وساعة ذهبية قد تعمل لحفلات زفاف خارجية بضوء دافئ: تعزز توهج الغروب، لكنها قد تصبغ الفستان أصفر أيضًا، فراجع البيض بعناية. وتباين عالٍ ودرامي هما أسوأ مرشحات زفاف: ظلال عميقة تسنّ الزوجين وتجعل الفستان يبدو رماديًا، وهو عكس ما يحتاجه ألبوم زفاف.</p>\n<p>واستخدم نفس المرشح لمجموعة الزفاف كلها: ألبوم حيث كل صورة تشترك في نفس المرشح الناعم يبدو احترافيًا، بينما مرشحات مختلطة تجعل اليوم يشعر بالتفكك.</p>\n<p>للعملية خطوة بخطوة، راجع <a href=\"/ar/blog/kayfiyya-tatbiq-murashshahat-ala-as-suwar/\">كيف تطبق مرشحات الصور</a> والدليل الكامل في <a href=\"/ar/blog/dalil-murashshahat-as-suwar/\">مرشحات الصور: دليل كامل</a>. ولضبط الألوان بدقة بدل تعديل سريع، جرّب <a href=\"/ar/taadil-tashabbu-as-sura/\">محرر تشبع الصور</a>. وقارن الأنماط الـ11 بصورك في <a href=\"/ar/murashshahat-as-suwar/\">مرشحات الصور</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"أي مرشح يجب أن أستخدم لخلاصة إنستغرام متسقة؟","answer":"اختر مرشحًا وشدة، واستخدمهما للخلاصة كلها، مثل فينتج بنسبة 50 بالمئة: مرشح متسق يبني أسلوبًا مميزًا، بينما مرشحات مختلطة تبدو عشوائية. وجرّب مرشحك في أنواع صور مختلفة قبل الالتزام."},{"question":"ما الفرق بين مرشحي فينتج وسيبيا؟","answer":"سيبيا يضيف صبغة بنية دافئة وقوية تشعر بالقدم والتاريخ، بينما فينتج يبهت الألوان بلطف، بمظهر فيلم أخف: سيبيا يناسب صورًا تاريخية وذكريات، وفينتج يناسب صورًا عفوية ومنشورات اجتماعية."},{"question":"هل أستخدم تدرج رمادي أم أبيض وأسود نوير لبورتريه؟","answer":"تدرج رمادي لبورتريه هادئ وتوثيقي، وأبيض وأسود نوير لواحد درامي بتعبير قوي: نوير يضيف تباينًا يؤكد العينين والعاطفة، بينما تدرج رمادي يُظهر الوجه كما هو دون دراما."},{"question":"هل استخدام مرشح أفضل أم ضبط التشبع يدويًا؟","answer":"مرشح أسرع ويعطي مظهرًا منسقًا بنقرة واحدة، ما يناسب منشورات اجتماعية وتعديلات سريعة: والتشبع اليدوي يعطي تحكمًا دقيقًا في جانب واحد، ما يناسب صورًا تحتاج ضبط لون دقيق."},{"question":"لماذا تبدو صوري المرشحة مختلفة عن بعضها؟","answer":"غالبًا تستخدم مرشحًا أو شدة مختلفة في كل صورة: اختر مرشحًا وشدة لسلسلة، وغيّر فقط الشدة قليلًا حسب الشخص. واختيار متسق يبني أسلوبًا، بينما اختيارات مختلطة تبدو عشوائية."},{"question":"هل يستطيع مرشح جعل صورة سيئة جيدة؟","answer":"لا، مرشح يغيّر الجو والألوان، لكنه لا يستطيع إصلاح صورة ضبابية أو داكنة أو سيئة التأطير: أصلح السطوع والتركيز والتأطير أولًا، ثم اختر مرشحًا يعزز الصورة الجيدة التي لديك."}];
